import{_ as o}from"./chunks/mockloc-icon.EUdWvRF7.js";import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.Crpw6aS5.js";const l="/assets/01-routes.DXnVWCaY.png",n="/assets/02-editor-road-route.7so4eylt.png",s="/assets/03-playback.DwCkavPR.png",f=JSON.parse('{"title":"MockLoc","description":"Developer tool for mocking GPS routes on Android — Google Play notes.","frontmatter":{"title":"MockLoc","description":"Developer tool for mocking GPS routes on Android — Google Play notes."},"headers":[],"relativePath":"software-engineering/android-app-development/play-google-com-mockloc.md","filePath":"software-engineering/android-app-development/play-google-com-mockloc.md"}'),c={name:"software-engineering/android-app-development/play-google-com-mockloc.md"};function d(p,e,u,h,m,g){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="mockloc" tabindex="-1">MockLoc <a class="header-anchor" href="#mockloc" aria-label="Permalink to &quot;MockLoc&quot;">​</a></h1><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Type: webpage</li><li>Origin: <a href="https://play.google.com/store/apps/details?id=com.mockloc" target="_blank" rel="noreferrer">Google Play — MockLoc</a></li><li>Imported: 2026-07-31</li></ul><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><p><img src="'+o+'" alt="MockLoc icon"></p><p><strong>Developer:</strong> Devin Carl Norgarb · <strong>Package:</strong> <code>com.mockloc</code> · <strong>Category:</strong> Tools · <strong>Updated:</strong> Jul 12, 2026</p><p>MockLoc is a developer tool for testing location-based Android apps. Define GPS routes, save them locally, and replay them at a fixed speed through Android’s built-in mock location provider — no root required.</p><p>Built for Android developers, QA engineers, and anyone shipping apps that depend on GPS, geofencing, navigation, fitness tracking, or real-time location updates.</p><h3 id="why-mockloc" tabindex="-1">Why MockLoc? <a class="header-anchor" href="#why-mockloc" aria-label="Permalink to &quot;Why MockLoc?&quot;">​</a></h3><p>Testing location features on a real device usually means walking, driving, or faking coordinates one point at a time. MockLoc lets you script realistic movement along a full route so you can reproduce bugs, demo features, and validate edge cases from your desk.</p><h3 id="create-routes" tabindex="-1">Create routes <a class="header-anchor" href="#create-routes" aria-label="Permalink to &quot;Create routes&quot;">​</a></h3><ul><li>Draw waypoints on an interactive map</li><li>Snap routes to roads with turn-by-turn geometry (Mapbox Directions)</li><li>Import GPX files from fitness trackers, mapping tools, or test fixtures</li><li>Save routes to a local library with distance and duration estimates</li></ul><h3 id="realistic-gps-playback" tabindex="-1">Realistic GPS playback <a class="header-anchor" href="#realistic-gps-playback" aria-label="Permalink to &quot;Realistic GPS playback&quot;">​</a></h3><ul><li>Replay routes at a fixed speed in km/h or mph</li><li>Configurable GPS accuracy radius (3–50 m)</li><li>Start, pause, resume, stop, and loop playback</li><li>Background replay via a foreground service — keeps running when you switch apps</li><li>Native interpolation delivers smooth lat/lng, bearing, and speed updates</li></ul><h3 id="developer-workflow" tabindex="-1">Developer workflow <a class="header-anchor" href="#developer-workflow" aria-label="Permalink to &quot;Developer workflow&quot;">​</a></h3><ul><li>Uses <strong>Android Developer Options → Select mock location app</strong> (standard test provider)</li><li>On-device route library — no account, no cloud sync required</li><li>Step-by-step setup guide for enabling mock location</li><li>Works with any app that reads the device GPS location</li></ul><h3 id="typical-use-cases" tabindex="-1">Typical use cases <a class="header-anchor" href="#typical-use-cases" aria-label="Permalink to &quot;Typical use cases&quot;">​</a></h3><ul><li>Test ride-share, delivery, or fleet apps along realistic paths</li><li>Validate geofence entry and exit without leaving the office</li><li>QA navigation, maps, and turn-by-turn features</li><li>Demo location-aware features to stakeholders</li><li>Replay recorded GPX tracks for regression testing</li></ul><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><ol><li>Enable Developer Options on your Android device</li><li>Select MockLoc as your mock location app</li><li>Create or import a route in the Editor</li><li>Open Playback, set speed, and tap Start</li><li>Switch to the app you’re testing — its location follows your route</li></ol><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><ul><li>Android device with Developer Options enabled</li><li>Internet connection for road-following route creation (saved routes replay offline)</li><li>Location permission (used to center the map)</li></ul><h3 id="intended-use" tabindex="-1">Intended use <a class="header-anchor" href="#intended-use" aria-label="Permalink to &quot;Intended use&quot;">​</a></h3><p>MockLoc is designed exclusively for legitimate development and quality-assurance testing of apps you own or are authorized to test. It is not intended for cheating in games, bypassing restrictions, or any deceptive use.</p><h3 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h3><p>Routes and settings are stored locally on the device. MockLoc does not require an account. Play Data safety: no data shared with third parties; no data collected.</p><h3 id="figures" tabindex="-1">Figures <a class="header-anchor" href="#figures" aria-label="Permalink to &quot;Figures&quot;">​</a></h3><p><img src="'+l+'" alt="MockLoc routes library"></p><p><img src="'+n+'" alt="MockLoc editor — road-snapped route"></p><p><img src="'+s+'" alt="MockLoc playback controls"></p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li><strong>MockLoc</strong> (<code>com.mockloc</code>) replays drawn, road-snapped, or GPX routes through Android’s mock-location provider — no root.</li><li>Stack: Ionic Vue + Capacitor, Mapbox maps/directions, local SQLite route library.</li><li>Store link: <a href="https://play.google.com/store/apps/details?id=com.mockloc" target="_blank" rel="noreferrer">MockLoc on Google Play</a></li></ul>',32)])])}const b=a(c,[["render",d]]);export{f as __pageData,b as default};
